L118:       const api = "https://api.frankfurter.dev";
L119:       return fetch(`${api}/v2/rate/${base}/${quote}`)
L120:         .then((r) => r.json())
L121:         .then((d) => (amount * d.rate).toFixed(2));
L122:     }
L123: 
