data class TimeSeriesDto(
    @SerialName("base") val base: String,
    @SerialName("start_date") val startDate: String,
    @SerialName("end_date") val endDate: String,
    @SerialName("rates") val rates: Map<String, Map<String, JsonPrimitive>>,
)
