package com.fxrates.data.remote

import com.fxrates.data.remote.dto.TimeSeriesDto
import io.ktor.client.HttpClient
import io.ktor.client.call.body
import io.ktor.client.request.get
import io.ktor.client.request.parameter
import kotlinx.datetime.LocalDate
import me.tatarka.inject.annotations.Inject

/** The Frankfurter API (https://frankfurter.dev): ECB reference rates, no key required. */
@Inject
class FrankfurterApi(
    private val httpClient: HttpClient,
) {

    /** Currency code → English name. */
    suspend fun getCurrencies(): Map<String, String> = httpClient.get("currencies").body()

    /**
     * Requests an inclusive business-day series with both boundaries explicit to avoid
     * the open-ended v1 route that has returned upstream timeouts.
     */
    suspend fun getTimeSeries(base: String, start: LocalDate, end: LocalDate): TimeSeriesDto {
        require(start <= end) { "Time series start must not be after end" }
        val path = "$start..$end"
        return httpClient.get(path) {
            parameter("base", base)
        }.body()
    }

}
package com.fxrates.data.repository

import com.fxrates.data.remote.FrankfurterApi
import com.fxrates.domain.model.CurrencyRate
import com.fxrates.domain.model.CurrencyRateHistory
import com.fxrates.domain.repository.RatesRepository
import kotlinx.coroutines.async
import kotlinx.coroutines.coroutineScope
import kotlinx.datetime.DatePeriod
import kotlinx.datetime.TimeZone
import kotlinx.datetime.minus
import kotlinx.datetime.todayIn
import me.tatarka.inject.annotations.Inject
import kotlin.time.Clock

@Inject
class RatesRepositoryImpl(
    private val api: FrankfurterApi,
    private val converter: RatesConverter,
    private val clock: Clock,
) : RatesRepository {

    override suspend fun getLatestRates(base: String): List<CurrencyRate> = coroutineScope {
        // Look back a week to compare available business days across weekends and ECB holidays.
        val endDate = clock.todayIn(TimeZone.UTC)
        val startDate = endDate.minus(DatePeriod(days = LOOKBACK_DAYS))
        val currencies = async { api.getCurrencies() }
        val timeSeries = async { api.getTimeSeries(base = base, start = startDate, end = endDate) }
        converter.toLatestRates(timeSeries = timeSeries.await(), currencies = currencies.await())
    }

    override suspend fun getRateHistory(base: String, code: String): CurrencyRateHistory {
        val endDate = clock.todayIn(TimeZone.UTC)
        val startDate = endDate.minus(DatePeriod(days = HISTORY_DAYS - 1))
        val timeSeries = api.getTimeSeries(base = base, start = startDate, end = endDate)
        return converter.toRateHistory(
            timeSeries = timeSeries,
            base = base,
            code = code,
            startDate = startDate,
            endDate = endDate,
        )
    }

    private companion object {

        const val LOOKBACK_DAYS = 7
        const val HISTORY_DAYS = 30

    }

}
package com.fxrates.data.repository

import com.fxrates.data.remote.dto.TimeSeriesDto
import com.fxrates.domain.model.CurrencyRate
import com.fxrates.domain.model.CurrencyRateHistory
import com.fxrates.domain.model.RateHistoryPoint
import com.ionspin.kotlin.bignum.decimal.BigDecimal
import com.ionspin.kotlin.bignum.decimal.toBigDecimal
import kotlinx.datetime.LocalDate
import kotlinx.serialization.json.JsonNull
import kotlinx.serialization.json.JsonPrimitive
import me.tatarka.inject.annotations.Inject

@Inject
class RatesConverter {

    /**
     * Takes the last two dates of [timeSeries] as "latest" and "previous". A currency with no
     * name in [currencies] is still shown, under its code. Uses actual quote dates, even when
     * today's quote is unpublished or non-trading days leave gaps; missing days are not filled.
     */
    fun toLatestRates(timeSeries: TimeSeriesDto, currencies: Map<String, String>): List<CurrencyRate> {
        val datesDescending = timeSeries.rates.keys.sortedDescending()
        val latestDate = datesDescending.firstOrNull() ?: return emptyList()
        val latest = timeSeries.rates.getValue(latestDate)
        val previous = datesDescending.getOrNull(1)?.let(timeSeries.rates::getValue).orEmpty()
        return latest
            .map { (code, rate) ->
                CurrencyRate(
                    code = code,
                    name = currencies[code] ?: code,
                    date = LocalDate.parse(latestDate),
                    rate = rate.toDecimal(),
                    previousRate = previous[code]?.toDecimal(),
                )
            }
            .sortedBy(CurrencyRate::code)
    }

    fun toRateHistory(
        timeSeries: TimeSeriesDto,
        base: String,
        code: String,
        startDate: LocalDate,
        endDate: LocalDate,
    ): CurrencyRateHistory {
        val points = timeSeries.rates.mapNotNull { (date, rates) ->
            val rate = rates[code] ?: return@mapNotNull null
            val quoteDate = LocalDate.parse(date)
            if (quoteDate !in startDate..endDate) return@mapNotNull null
            RateHistoryPoint(date = quoteDate, rate = rate.toDecimal())
        }.sortedBy(RateHistoryPoint::date)
        return CurrencyRateHistory(
            base = base,
            code = code,
            startDate = startDate,
            endDate = endDate,
            points = points,
        )
    }

    private fun JsonPrimitive.toDecimal(): BigDecimal {
        require(!isString && this != JsonNull) { "Expected a numeric rate" }
        return content.toBigDecimal()
    }

}
package com.fxrates.domain.model

import com.ionspin.kotlin.bignum.decimal.BigDecimal
import kotlinx.datetime.LocalDate

/**
 * The latest rate of [code] against the base currency.
 *
 * @property rate how many units of [code] one unit of the base currency buys.
 * @property previousRate the rate on the previous business day; `null` when the API has no
 * earlier quote in the requested window.
 */
data class CurrencyRate(
    val code: String,
    val name: String,
    val date: LocalDate,
    val rate: BigDecimal,
    val previousRate: BigDecimal?,
)
package com.fxrates.feature.rates.list

import com.fxrates.core.format.NumberFormatter
import com.fxrates.core.money.RateChangeCalculator
import com.fxrates.core.utils.Empty
import com.fxrates.core.utils.Resource
import com.fxrates.domain.model.CurrencyRate
import com.fxrates.feature.rates.list.RatesListUiState.Content
import com.fxrates.feature.rates.list.model.RateItem
import com.fxrates.feature.rates.list.model.Trend
import com.fxrates.feature.rates.list.mvi.RatesListStore
import com.fxrates.ui.Strings
import me.tatarka.inject.annotations.Inject

@Inject
internal class RatesListUiStateConverter {

    fun createUiState(state: RatesListStore.State): RatesListUiState {
        val rates = state.rates
        val subtitle = when (rates) {
            is Resource.Data -> {
                rates.value.firstOrNull()?.let { rate -> Strings.ratesSubtitle(state.base, rate.date.toString()) }
                    ?: String.Empty
            }
            is Resource.Loading, is Resource.Error -> {
                String.Empty
            }
        }
        return RatesListUiState(
            subtitle = subtitle,
            query = state.query,
            isRefreshEnabled = rates !is Resource.Loading,
            content = createContent(rates = rates, query = state.query),
        )
    }

    private fun createContent(rates: Resource<List<CurrencyRate>>, query: String): Content = when (rates) {
        is Resource.Loading -> {
            Content.Loading
        }
        is Resource.Error -> {
            Content.Error
        }
        is Resource.Data -> {
            val items = rates.value
                .filter { rate -> rate.matches(query.trim()) }
                .map(::toItem)
            if (items.isEmpty()) Content.NothingFound else Content.Items(items)
        }
    }

    private fun CurrencyRate.matches(query: String): Boolean {
        return query.isEmpty() || code.contains(query, ignoreCase = true) || name.contains(query, ignoreCase = true)
    }

    private fun toItem(rate: CurrencyRate): RateItem {
        val change = rate.previousRate?.let { previous -> RateChangeCalculator.calculate(previous, rate.rate) }
        val trend = when {
            change == null || change.absolute.isZero() -> Trend.Flat
            change.absolute.isPositive -> Trend.Up
            else -> Trend.Down
        }
        return RateItem(
            code = rate.code,
            name = rate.name,
            rate = NumberFormatter.formatRate(rate.rate),
            change = change?.percent?.let(NumberFormatter::formatSignedPercent),
            trend = trend,
        )
    }

}
package com.fxrates.ui

/**
 * Every user-facing string of the app. The app is English-only, so a constant is enough; a
 * string is never written inline in a composable.
 */
object Strings {

    const val RATES_TITLE = "Rates"
    const val RATES_SEARCH_HINT = "Search by code or name"
    const val RATES_NOTHING_FOUND = "Nothing found"
    const val ERROR_TITLE = "Could not load the rates"
    const val RETRY = "Retry"
    const val REFRESH = "Refresh"

    fun ratesSubtitle(base: String, date: String): String = "1 $base · $date"

}
