                uiStateConverter = RatesDetailsUiStateConverter(),
                computationDispatcher = testDispatcher,
            )
            try {
                runCurrent()
                repository.requestedPairs shouldBe listOf("GBP" to "JPY")
            } finally {
                lifecycle.destroy()
            }
            runCurrent()

            cancelled shouldBe true
        }
    }

})
